// Content for the "Products, in focus" showcase (Collection 02, active-product layout).
// Collection 01 lives in ./standardPacks.ts and renders as product cards.
//
// Every value below was read from the product label in the owner's photos
// (public/WhatsApp Unknown 2026-10-09 at 9.16.48 PM). Leave a field out when it
// is not confirmed; the section only renders the fields that are present.
//
// Images are transparent cut-outs generated by scripts/cutout-products.cjs into
// public/images/products/showcase/<id>(.avif|.webp) plus a <id>-560 variant.

export type ShowcaseProduct = {
  id: string
  /** Product name as printed on the label. */
  name: string
  /** Concentration, grade or stabiliser line printed under the name. */
  qualifier?: string
  formula?: string
  cas?: string
  /** Piochem catalogue number ("CAT No." on the label). */
  code?: string
  grade?: string
  packSize?: string
  /** Pixel size of the full-resolution cut-out. */
  width: number
  height: number
}

export type ShowcaseCollection = {
  id: string
  index: string
  title: string
  copy: string
  products: ShowcaseProduct[]
}

